class Student:
    def __init__(self, name, house):
        if house not in ["Gryffindor", "Hufflepuff", "Ravenclaw", "Slytherin"]:
            raise ValueError("Invalid house")
        self.name = name
        self.house = house

    def __str__(self):
        return f"{self.name} from {self.house}"

print(Student("Harry", "Gryffindor"))
try:
    Student("Padma", "Number Four, Privet Drive")
except ValueError as e:
    print("refused:", e)

class Student:
    def __init__(self, house):
        self.house = house

    @property
    def house(self):
        return self._house

    @house.setter
    def house(self, house):
        if house not in ["Gryffindor", "Slytherin"]:
            raise ValueError("Invalid house")
        self._house = house

s = Student("Gryffindor")
try:
    s.house = "Privet Drive"
except ValueError:
    print("setter blocked it; still", s.house)

