class Vault:
    def __init__(self, galleons=0):
        self.galleons = galleons

    def __add__(self, other):
        return Vault(self.galleons + other.galleons)

print(Student("Harry", "Gryffindor").name)
print((Vault(100) + Vault(25)).galleons)

